{
  "name": "update_plan",
  "description": "Update the task checklist. Keep only one step in_progress at a time.",
  "parameters": {
    "type": "object",
    "properties": {
      "steps": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "title": { "type": "string" },
            "status": {
              "type": "string",
              "enum": ["pending", "in_progress", "done", "skipped"]
            }
          },
          "required": ["title", "status"],
          "additionalProperties": false
        }
      }
    },
    "required": ["steps"],
    "additionalProperties": false
  }
}
